#!/usr/bin/env python3
from common import fail
'Portable lane brief. See the openproblem README for inputs.'
from common import Context, REPO, entry, lane_spec

def main(argv):
    ctx = Context(argv[1])
    import sys, json, pathlib, re
    sp = pathlib.Path(argv[1])
    spec = lane_spec(argv[2])
    repo = REPO
    base = (repo / 'tools/scripts/agent/openproblem/templates/impl-base-brief.md').read_text()
    goal = (sp / 'briefs/goal-artifact.yaml').read_text().split('\n', 1)[1]
    goal = '\n'.join((l[2:] if l.startswith('  ') else l for l in goal.splitlines()))
    L = spec['lane']
    mod = spec['module']
    name = mod.rsplit('/', 1)[1]

    def sub(pattern, repl, text, flags=re.S):
        new, n = re.subn(pattern, lambda m: repl, text, count=1, flags=flags)
        if n != 1:
            fail(13, f'anchor not found: {pattern[:60]!r}')
        return new
    t = base
    t = sub('\\A# .*?\\n', f"# sshx implementation-seat brief — lane `op-{L}` — {spec['title']} (probe-verified; same-PR deposit + cover; open the PR, no auto-merge)\n", t)
    t = re.sub('(## GoalArtifact \\(complete; cite in visible_inputs\\)\\n```yaml\\n).*?(\\n```)', lambda m: m.group(1) + goal.rstrip() + m.group(2), t, count=1, flags=re.S)
    t = sub('## Worktree\\n.*?(?=\\n## )', f"""## Worktree\n`{spec['worktree']}` (branch `{spec['branch']}`, created from `origin/dev` by `make worktree`; reused by every stage of this lane). Toolchain: `eval "$(sed -n '/^export PATH=/p' tools/scripts/local-harness-gate.sh)"`, then `make -C tools dotnet` once. `git status --short` must be empty before you start (Stage A) or must contain exactly Stage A's files (Stage B).\n""", t)
    t = sub('## Target \\(probe-verified\\)\\n.*?(?=\\n## Steps)', '## Target (probe-verified)\n' + spec['target_md'].rstrip() + '\n', t)
    t = t.replace('D5/S3/PrimeForms/PrimaryPseudoperfectPorts', mod)
    t = sub('\\n5\\. \\*\\*Deposit / cover\\*\\*.*?(?=\\n6\\. ONE builder commit)', '\n5. **Deposit / cover** (same PR, same tree; external named open problem, so NO atom and NO cover: CLAUDE.md §1.2 exception and §3.2 「开放问题结算依据」): before any freeze, independently confirm the module\'s declarations and the §3.2 open-problem-resolution conditions (a)–(d): the delivered public surface is only the definitions the settlement needs plus `claim` and the one settling `result`; every private theorem/lemma is either genuine content or inlined. Then, in ONE command, `B="$(git merge-base HEAD origin/dev)" && git merge-base --is-ancestor "$B" HEAD && make deposit-uncovered GID=' + spec['gid'] + ' BASE="$B"` (`origin/dev` is shared by every worktree and moves while other seats fetch; `B` is the dev commit this tree actually merged, so pass that SHA, never the moving ref; freshness against the latest dev is the CI merge-tree check) EXIT=0 (on `LEDGER_ALIGN_FAILED` / `dependency-not-ready`: STOP, report `open`, no retry, no hand edits; on `DEPOSIT_HEADER_CHECK_INVALID … ancestor`: merge origin/dev, re-run `make lean LEAN_TARGETS="<the delivered modules and every frozen module you re-pin, dotted>"`/`make lean-report-scoped LEAN_TARGETS="<the same list>"`, late dedupe, retry — a continuation, not a redo). Check the NEW Freeze event\'s `prerequisite_frozen_node_ids` (expected empty unless a D5 module is imported); report the mapping.', t)
    t = re.sub('with subject `formalize: deposit PrimaryPseudoperfectPorts \\(PZG 4\\.91–4\\.95\\)`', lambda m: f"with subject `{spec['commit_subject']}`", t)
    t = t.replace('lane/math/op-w1-ppn', spec['branch']).replace('pr-op-w1-ppn.md', f'pr-op-{L}.md')
    t = sub('\\n1′\\. \\*\\*Classify before implementation.*?(?=\\n2\\. \\*\\*Module\\*\\*)', "\n1′. **Classify before implementation (`CLAUDE.md` §3.2, open-problem-resolution lane):** this lane settles an EXTERNAL NAMED open problem that was preregistered before any Lean (see the Target). Under §3.2 「开放问题结算依据」 the settling public `result` may be bind-only and still be frozen, provided conditions (a)–(d) hold: (a) the public surface is only the definitions the settlement needs plus `claim` and the one `result` — no companion theorem, no public wrapper, no public helper lemma; (b) every declaration reports its true `proof_shape` (bind-only is written as bind-only); (c) the Scribe carries `OpenProblemResolutionClaim` (Stage B) and the `Problems/` dossier; (d) the §3.3 utility header is judged as usual. So do NOT stop because `result` is bind-only; DO stop if you would need a second public theorem. Every PRIVATE theorem/lemma is still judged one by one under the bind-only ban (see the paragraph above): keep it only if it is genuine content, otherwise inline it as a `have`. Report `proof_shape`, `escape_witness` (or `none`) and `admission_basis: open-problem-resolution (#<issue>; <Proved|Refuted>)` in the module's second comment block, the PR body and the envelope.", t)
    t = t.replace('<<OP_SCRATCH>>', str(sp))
    for bad in ('PrimaryPseudoperfect', 'op-w1-ppn', '857a54840bc4'):
        if bad in t:
            fail(13, f'leftover template token {bad!r}')
    extra = '\n\n## Escape audit (CLAUDE.md §3.9 at origin/dev; binding)\nEach newly authored public D5 `theorem`/`lemma` in the delivery is an audit target. The designated refutation result (`utility: … basis=refutes; result=…`) is exempt.\n\n**Refutation-only modules.** If the only public theorem is that exempt result, state it in one sentence in the module comment, the dossier and the PR body: "The public result is the designated refutation result (`basis=refutes`) and is exempt from four-slot escape registration (CLAUDE.md §3.9)."\n\n**For every other audit target**, attempt a faithful four-slot registration in the same delivery:\n- Write `Reg/D5/<the module\'s mirrored path>.lean`, using a typed `Contract.Registration` whose `readout` applies an already-enrolled template.\n- Search `Reg/Support/**`, for example `PointwiseEqualityRegistrations`, `PointwiseOrderRegistrations`, `GuardedEqualityRegistrations`, `IffRegistrations`, `ExistentialWitnessRegistrationTemplates` and `DependentFamily`, and the existing `Reg/D5/**` mirrors for a template that lawfully reads the theorem\'s statement.\n- Follow `skills/codex-formalize/SKILL.md` "Escape-audit delivery" and spec A5.5/A5.6.\n- Compile the Reg module through `make lean LEAN_TARGETS="<the delivered modules and every frozen module you re-pin, dotted>"`.\n- Before the push, record the registration as "pending CI reading"; never write `declared_validated` without the CI reading.\n- After pushing the delivery head, read the DTR finding for each audit target from its required CI `current` job: run `gh run view <run-id> --log --job <current-job-id>` and search the `DTR-` lines. Report each finding with the run id and job id; `DTR-Declared` means complete.\n\n**If registration is missing, invalid or blocked** (no lawful template, failed E1–E8 or bridge checks, or missing evidence):\n- Open one issue for this delivery, or reuse the lane\'s existing one: `gh issue create --title "Escape audit unfinished: <module>" --body-file …`.\n- Name each audit target, the concrete template gap or failure verdict with its readings (for example `DTR-Unregistered` from the required CI `current` job for the pushed delivery head, with its run id and job id), and the missing evidence.\n- Link the issue in the module comment (one line), the dossier and the PR body, and state that the escape audit is unfinished.\n- Continue the delivery.\n\n**Never:**\n- modify the judge (`tools/**`, inspector, judge Interface/Impl packages);\n- force a wrong template;\n- weaken a theorem or add bind-only wrappers;\n- claim `declared_validated` without the compiled evidence and the CI reading.\n\nReport registration as complete or unfinished with its linked issue; never write "paused".\n\n## Directory capacity (SL-003)\nBefore adding a file, count the target directory on fresh `origin/dev` (`git ls-tree --name-only origin/dev <dir>/ | wc -l`); the admission limit is 96 entries. `Library/Quantum` (96) and `Library/QuantumStates` (97) are full: put a new quantum note in a registered Library domain directory with room, such as `Library/QuantumBounds/` or `Library/QuantumChannels/` (count it first); never add a file to a directory that already holds 96 or more entries.\n\n## Foreign projections\n`make emit` may rewrite projections of other deliveries (e.g. `Blueprint/D5/S3/VertexAlgebra/MonsterTwistedOctonionNorm.md`). Before every commit, `git diff --name-only origin/dev...HEAD -- Blueprint; git diff --name-only -- Blueprint` must name only this lane\'s `.scribe.cs`/`.md`; restore any other path to the exact `origin/dev` bytes (`git checkout origin/dev -- <path>`). A delivery that changes another module\'s projection is a blocking review finding.\n\n## Scribe binders\n**Same-delivery owners (reuse sweep).** Check every helper and every closed local `have` also against every other declaration of this delivery (all delivered modules, private included): a local fact that restates an earlier declaration of the delivery, or a specialization of it, is replaced by an application of that declaration (move the declaration earlier if needed; it stays private unless another module consumes it). `exact?` does not see private same-module declarations, so test each candidate by a compiled direct application.\n\n**The settling theorem shows its full statement.** The Scribe node of `result` (and of every public theorem) renders the full proposition it proves: for `result : claim` (or `¬ claim`) the formula expands the claim\'s body (for instance through a `ClaimBody()` helper shared with the `claim` definition node), never `X("claim")` or another bare reference to the name. A theorem node whose formula is only the name of a definition is a blocking mirror finding.\n\nEvery formula in the Scribe mirror is closed: (1) each public definition\'s displayed formula binds ALL of its parameters with their types (e.g. `∀ (V : Type) (G : SimpleGraph V) (C : Finset V), condense G C = …`), never leaving `V`, `G`, `C` free; (2) Lean instance arguments (`[Fintype V]`, `[DecidableEq V]`, `[Group G]`) are rendered as anonymous bracket items (`Seq(…, OpenBracket, Call("Fintype", v), CloseBracket, …)`), NEVER as named binders (`All("FV", Call("Fintype", v), …)` leaves `FV` unused and is a FAIL); (3) every named binder occurs in its body. Before Stage A ends, read the emitted `.md` formula by formula and check (1)–(3).\n\n## What the settlement shows (CLAUDE.md §3.6)\nThe `Problems/` dossier states the new information the settlement yields, each statement marked proved in this module, computed (with the command) or open. Refuted: the failure mechanism (which hypothesis or structure the witness breaks) and the nearest statements that survive. Proved: the decisive mechanism (identity, invariant, estimate) and how far it extends (relaxed hypotheses, sharpness, neighbouring questions the argument settles). Both: what changes for the source\'s other results that relied on the conjecture. Write it inside the dossier\'s `## Triage` section as a `### What the settlement shows` subsection: the dossier\'s `##` sections are a closed set (Problem, Motivation, Gap, Route, Falsifier, Evidence, Triage, ASSUMED-UNVERIFIED) and a new `##` heading fails the Problems catalog check. Do not add new statements to this module; list follow-up candidates in the envelope under `follow_up_candidates`.\n\n## Reuse every existing declaration (CLAUDE.md §3.1, §4.3)\nBefore writing any `def`, `abbrev`, `instance` (named or anonymous), `structure` or `notation`, public or private, fetch `origin/dev` and search for an existing one by content: the modules you import and their D5 owners (an imported module that already provides the `Fintype`/`DecidableEq` instance or the operator is the most frequent duplicate), `git grep origin/dev -- D5` for the defining expression and its equivalent textbook forms (`Matrix.circulant` for a shift, `Matrix.vecMulVec v (star v)` for a rank-one projector, `Matrix.diagonal (Pi.single k 1)` for a basis state), and pinned Mathlib. If one exists, use it directly (remove `private` at the owner if needed; no wrapper or forwarding lemma). List every searched declaration with command, exit code and hit in the PR body search trace.\n\n## PR body session line (CLAUDE.md §5.2)\n'
    extra += ctx.provenance
    t = t.replace('\n## Steps', extra + '\n## Steps', 1)
    out = sp / 'briefs' / f'impl-op-w1-{L}.md'
    out.write_text(t)
    print(out, len(t))
if __name__ == '__main__':
    import sys
    sys.exit(entry(main, minimum=2, maximum=2))
